import{_ as t,p as n,q as s,s as e,R as a,t as c,Y as o,n as p}from"./framework-e1bed10d.js";const d="/my-blog/assets/046_01-eb5d4aad.png",i="/my-blog/assets/046_02-b78f04d0.png",h={},_=e("h1",{id:"会计基础-程序员能懂的借贷",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#会计基础-程序员能懂的借贷","aria-hidden":"true"},"#"),a(" 会计基础：程序员能懂的借贷")],-1),l={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247485061&idx=1&sn=0a496c8413b64ce0ecd02c42aa50781a&chksm=e8c6f6f9dfb17fefe7bc0eeca2d84ce01977dc79e5967a6de41f0e8c503e379333b962ae6e0a",target:"_blank",rel:"noopener noreferrer"},f=o('<hr><p><strong>第六章　核算与会计引擎：从会计分录到总账</strong></p><p>第五章讲了核心系统怎么管借据、怎么算利息。这一章回答一个问题：这些业务动作，最后是怎么变成账本上的一行行记录的？在金融机构，“账”是比系统更古老、也更严肃的东西，系统可以重启，账不能重记。</p><p>核算是信贷系统的账本，也是监管和审计最关注的部分。这一章从会计基础讲到会计引擎，再到账户体系、日终对账和GLP（老一代总账处理模块）改造实战，整体路线见图6-1；读完你应该能看懂会计分录，也能说清会计引擎怎么设计。</p><p>我在互金平台主导核算系统改造时，花了最多时间的不是写代码，而是和财务人员一笔一笔对分录。因为程序员理解的交易和财务理解的分录，中间隔着一层翻译，这层翻译做不好，系统再快也没用。</p><p><img src="'+d+'" alt="图片"></p><p><strong>图6-1 核算与会计引擎全章总览：从业务动作到总账</strong></p><h2 id="一、会计基础-程序员能懂的借贷" tabindex="-1"><a class="header-anchor" href="#一、会计基础-程序员能懂的借贷" aria-hidden="true">#</a> 一、会计基础：程序员能懂的借贷</h2><h3 id="一-为什么记账要用借贷记账法" tabindex="-1"><a class="header-anchor" href="#一-为什么记账要用借贷记账法" aria-hidden="true">#</a> （一）为什么记账要用借贷记账法</h3><p>很多程序员一听会计就头疼。其实信贷系统要用的会计知识就一块基石：借贷记账法。它背后的逻辑是会计恒等式：资产=负债+所有者权益。左边是“公司有什么”（资产，资金的使用方），右边是“这些东西怎么来的”（负债和所有者权益，资金的来源）。</p><p>每一笔业务，资金都有来源和去处，所以“有借必有贷，借贷必相等”，这就是复式记账。为什么要复式而不是记一个数字？因为单边记账只记录了“钱去了哪”，丢掉了“钱从哪来”，账就解释不了自己。借贷记账法让每一笔账自带解释：借资产，必有对应的贷负债或贷收入来回答“钱从哪来”。</p><p>这也是为什么贷款要分科目记账：资产增加了，要回答它来自哪笔收入还是哪笔负债。会计科目把经济业务分类，会计分录（借/贷）是记账公式，两者都要遵循会计准则。</p><h3 id="二-权责发生制-没收到钱也要记收入" tabindex="-1"><a class="header-anchor" href="#二-权责发生制-没收到钱也要记收入" aria-hidden="true">#</a> （二）权责发生制：没收到钱也要记收入</h3><p>利息计提为什么要每天记应收利息？因为会计准则要求权责发生制：钱虽然没收到，但债权（应收利息）已经确定，就要记账。与之相对的是收付实现制：钱到了才记账。</p><p>企业用权责发生制，因为管理者需要及时知道自己的资产和负债，有哪些待收、有哪些待付；行政单位用收付实现制，因为只需要简单记账。信贷系统里，利息每天计提、挂应收利息，就是权责发生制的直接体现。</p><h3 id="三-会计分录-有借必有贷" tabindex="-1"><a class="header-anchor" href="#三-会计分录-有借必有贷" aria-hidden="true">#</a> （三）会计分录：有借必有贷</h3><p>分录是记账的基本单元。一笔放款，借记“发放贷款及垫款”，贷记“头寸”或“银行存款”；一笔利息收入，借记“应收利息”，贷记“利息收入”。借和贷不是加减，而是方向，资产类借方增加，负债类贷方增加，收入类贷方增加。</p><p>把这几条记牢，再看信贷分录就不会晕：资产类科目（贷款、应收利息）借方增加；负债类科目（头寸、客户存款、保证金）贷方增加；收入类科目（利息收入、手续费收入）贷方增加。</p><p>举个例子，银行放款100万元，资产端的正常本金增加100万，同时资产端的银行存款减少100万，等式两边不变；客户还款10万元，银行存款增加10万，正常本金减少8万、应收利息减少2万，等式仍然平衡。每一笔交易都要保证等式成立，这就是有借必有贷、借贷必相等。</p><p><img src="'+i+'" alt="图片"></p><p><strong>图6-2 会计基础：程序员能懂的借贷</strong></p>',21);function m(b,g){const r=p("ExternalLinkIcon");return n(),s("div",null,[_,e("blockquote",null,[e("p",null,[a("公众号：侃西东　·　发布日期：2026-11-01　·　"),e("a",l,[a("微信原文"),c(r)])])]),f])}const x=t(h,[["render",m],["__file","046.html.vue"]]);export{x as default};
